import java.io.*;
import java.net.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.Base64;

/**
 * Legacy session restoration endpoint for backward compatibility
 * with pre-2019 mobile clients that send serialized session objects.
 * 
 * NOTE: This endpoint is scheduled for deprecation in Q3 2025.
 * New clients use JSON-based session tokens (see /api/v2/session).
 */
public class LegacySessionServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;
    private static final int MAX_PAYLOAD_SIZE = 65536;

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String clientVersion = request.getHeader("X-Client-Version");
        if (clientVersion == null || clientVersion.isEmpty()) {
            response.sendError(400, "Missing client version header");
            return;
        }

        // Only legacy clients (< v3.0) use serialized sessions
        if (!isLegacyClient(clientVersion)) {
            response.sendError(400, "Use /api/v2/session for modern clients");
            return;
        }

        String encodedSession = request.getParameter("session_data");
        if (encodedSession == null || encodedSession.length() > MAX_PAYLOAD_SIZE) {
            response.sendError(400, "Invalid session data");
            return;
        }

        try {
            byte[] sessionBytes = Base64.getDecoder().decode(encodedSession);
            Object sessionObj = deserializeSession(sessionBytes);

            if (sessionObj instanceof SessionData) {
                SessionData session = (SessionData) sessionObj;
                // Validate session hasn't expired
                if (System.currentTimeMillis() - session.getTimestamp() > 86400000) {
                    response.sendError(401, "Session expired");
                    return;
                }
                request.getSession().setAttribute("user", session.getUserId());
                request.getSession().setAttribute("roles", session.getRoles());
                response.setStatus(200);
                response.getWriter().write("{\"status\":\"restored\"}");
            } else {
                response.sendError(400, "Invalid session object type");
            }
        } catch (ClassNotFoundException e) {
            response.sendError(500, "Session class not found");
        } catch (IllegalArgumentException e) {
            response.sendError(400, "Malformed base64 data");
        }
    }

    private Object deserializeSession(byte[] data) 
            throws IOException, ClassNotFoundException {
        ByteArrayInputStream bais = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bais);
        // Deserialize the session object - trusts client input
        Object obj = ois.readObject();
        ois.close();
        return obj;
    }

    private boolean isLegacyClient(String version) {
        try {
            String[] parts = version.split("\\.");
            int major = Integer.parseInt(parts[0]);
            return major < 3;
        } catch (Exception e) {
            return false;
        }
    }
}

class SessionData implements Serializable {
    private static final long serialVersionUID = 2L;
    private String userId;
    private String[] roles;
    private long timestamp;

    public String getUserId() { return userId; }
    public String[] getRoles() { return roles; }
    public long getTimestamp() { return timestamp; }
}
